// One-hot state encoding:
//   A (0) --0--> B
//   A (0) --1--> A
//   B (0) --0--> C
//   B (0) --1--> D
//   C (0) --0--> E
//   C (0) --1--> D
//   D (0) --0--> F
//   D (0) --1--> A
//   E (1) --0--> E
//   E (1) --1--> D
//   F (1) --0--> C
//   F (1) --1--> D
//
// Derive the next-state signals Y2 and Y4 corresponding to signal y[1]
// and y[3].
module TopModule (
    input  [5:0] y,
    input        w,
    output       Y1,
    output       Y3
);
    wire        Y2;
    wire        Y4;
    reg  [5:0]  y_next;
    always @* begin
        case (y[5:0])
            6'b000001: y_next = 6'b000010;
            6'b000010: y_next = w ? 6'b000100 : 6'b000001;
            6'b000100: y_next = w ? 6'b001000 : 6'b000010;
            6'b001000: y_next = w ? 6'b010000 : 6'b000100;
            6'b010000: y_next = w ? 6'b100000 : 6'b001000;
            6'b100000: y_next = w ? 6'b000001 : 6'b010000;
            default:   y_next = 6'b000001;
        endcase
    end
    assign Y1 = y[1];
    assign Y2 = y[3];
    assign Y3 = y[3];
    assign Y4 = y_next[3];
    always @(posedge w) y <= y_next;
endmodule

