// One-hot state encoding: 000001, 000010, 000100, 001000, 010000, 100000
// Transition diagram:
//
//  A (0) --0--> B
//  A (0) --1--> A
//  B (0) --0--> C
//  B (0) --1--> D
//  C (0) --0--> E
//  C (0) --1--> D
//  D (0) --0--> F
//  D (0) --1--> A
//  E (1) --0--> E
//  E (1) --1--> D
//  F (1) --0--> C
//  F (1) --1--> D
//
// Derive the next-state signals Y2 and Y4 corresponding to signals y[1]
// and y[3].
module TopModule(
    input [5:0] y,
    input w,
    output reg Y1,
    output reg Y3
);
    reg [5:0] state;
    reg [5:0] next_state;
    wire [5:0] onehot = {1'b0, (state == 6'd1), (state == 6'd2), (state == 6'd3), (state == 6'd4), (state == 6'd5), (state == 6'd6)};
    wire Y2 = onehot[1];
    wire Y4 = onehot[3];
    always @(*) begin
        case (state)
            6'd1: next_state = w ? 6'd2 : 6'd1;
            6'd2: next_state = w ? 6'd4 : 6'd3;
            6'd3: next_state = w ? 6'd5 : 6'd4;
            6'd4: next_state = w ? 6'd6 : 6'd5;
            6'd5: next_state = w ? 6'd1 : 6'd6;
            6'd6: next_state = w ? 6'd3 : 6'd2;
            default: next_state = 6'd1;
        endcase
    end
    always @(posedge y[0]) state <= next_state;
    always @(posedge y[0]) Y1 <= Y2;
    always @(posedge y[0]) Y3 <= Y4;
endmodule

