            6'b000010: y_hot = 6'b000010;
            6'b000100: y_hot = 6'b000100;
            6'b001000: y_hot = 6'b001000;
            6'b010000: y_hot = 6'b010000;
            6'b100000: y_hot = 6'b100000;
            default: y_hot = 6'b0;
